    FixtureView(Context c,ChatSession owner,NetworkSourcesRouteIntegrationActivity test){super(c,owner);this.test=test;}
    @Override public void loadUrl(String target){lastNavigation=test.session==null?null:new NavigationIntent(this,test.session,target);if(lastNavigation!=null){if(navigationIntents.size()<32)navigationIntents.addLast(lastNavigation);else navigationIntentOverflow=true;}test.recoveryEvent("load-url-before",J.obj("target",target,"state",test.recoveryState()));try{super.loadUrl(target);}finally{test.recoveryEvent("load-url-after",J.obj("target",target,"state",test.recoveryState()));}}
